  if (m) {
    const target = decode(m[1].split('#')[0].replace(/\.html$/, ''));
    redirects[f.replace(/\.html$/, '')] = target;
  }
}

const linksFrom = {}; // word -> Set of linked targets
const wordInfo = {};

for (const f of files) {
  if (CHROME.has(f)) continue;
  const stem = f.replace(/\.html$/, '');
  const html = fs.readFileSync(path.join(SITE, f), 'utf8');
  const h1m = html.match(/<main>[\s\S]*?<h1>([\s\S]*?)<\/h1>/);
  const tema = (html.match(/<p class="tema">([\s\S]*?)<\/p>/) || [])[1];
  const word = h1m ? h1m[1].trim() : stem;
  wordInfo[stem] = { file: f, h1: word, tema: tema ? tema.replace(/<[^>]+>/g, '').trim() : null };

  // Redirect alias pages: link only to canonical
  if (redirects[stem]) {
    linksFrom[stem] = new Set([redirects[stem]]);
